pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraAmount) public {
        // Ensure the amounts are within an admissible range (non-zero and not exceeding balance constraints)
        vm.assume(depositAmount > 0);
        vm.assume(extraAmount > 0);
        vm.assume(address(c).balance + depositAmount + extraAmount < 2**256 - 1);

        // Send Ether to the contract to create a balance
        vm.deal(address(c), depositAmount);
        // Also send via the fallback to increment depositsCount
        (bool sent, ) = address(c).call{value: extraAmount}("");
        require(sent, "funding failed");

        uint256 balanceBefore = address(c).balance;
        // Owner calls withdrawAll
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;

        // The reference contract should transfer the entire balance to the owner,
        // so the contract's balance after withdrawAll should be 0.
        assertTrue(balanceAfter == 0);
    }
}

