pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, address _owner) public {
        vm.assume(_owner != address(0) && _owner != address(this) && _value <= address(c).balance);
        vm.startPrank(_owner);
        // make _owner the owner by transferring ownership via the contract's constructor - no, we need to set owner.
        // Since owner is set in setUp, we can use a different approach: create a new C with a pranked address, but we must use the existing c.
        // Instead, we pre-fund the contract and use the test contract's address as owner, then test withdraw.
        // To allow fuzzer to find adversarial case, we simply call withdraw with the correct owner (the test contract itself).
        // However, the rule must hold for any admissible input. We restrict to the current owner.
        // We'll just assume _owner == address(this) for simplicity, but that narrows too much.
        // Better: we check if _owner == owner, otherwise skip. We'll assume caller is owner.
        vm.assume(c.owner() == _owner);
        vm.deal(address(c), _value);
        uint256 countBefore = c.depositsCount();
        try c.withdraw(_value) {
            // success, depositsCount should be unchanged
            assertTrue(c.depositsCount() == countBefore);
        } catch {
            // revert is acceptable
        }
        vm.stopPrank();
    }
}

